// Owns the Unicode rules of a source's logical name (IMPL 20.1) over the pinned Unicode 15.0.0 data (UnicodeNameData, generated by
// GenerateNameUnicode.ps1): NFC, and simple case folding (CaseFolding.txt's C and S mappings, never full folding: ß and ss differ).
// Input: names as UTF-16 text. Output: whether a name is NFC (UnicodeIdentifierHelper.IsNormalized, the one NFC check, over every
// scalar's combining class, which this owner publishes), a comparer under simple case folding, and the names' order as UTF-8 byte
// sequences (SPEC 6.2.1's logical declaration order). A lone surrogate stays its own code unit, never folded or replaced, and
// ill-formed text is not NFC. No allocation; no host culture or ICU data.

using System.Buffers;
using System.Text;

namespace Kimi.Compiler.Helper;

internal static class UnicodeNameHelper
{
    /// <summary>Gets the comparer of names under simple case folding (IMPL 20.1).</summary>
    internal static IEqualityComparer<string> SimpleCaseFolding { get; } = new Folding();

    /// <summary>Gets the order of names as UTF-8 byte sequences, which is Unicode scalar order (SPEC 6.2.1), computed on UTF-16 without
    /// encoding: at the first differing code unit, surrogates rank above U+E000–U+FFFF; a proper prefix comes first. A lone surrogate
    /// (a name that is not NFC) orders by its code unit, so the order stays total.</summary>
    internal static IComparer<string> ScalarOrder { get; } = new Scalar();

    /// <summary>Gets a value indicating whether a name is well-formed UTF-16 in NFC (IMPL 20.1).</summary>
    /// <param name="name">The name.</param>
    /// <returns><see langword="true"/> when the name is NFC.</returns>
    internal static bool IsNfc(string name)
    {
        if (Ascii.IsValid(name))
        {
            return true;
        }

        var index = 0;
        while (index < name.Length)
        {
            if (Rune.DecodeFromUtf16(name.AsSpan(index), out _, out var count) != OperationStatus.Done)
            {
                return false;
            }

            index += count;
        }

        return UnicodeIdentifierHelper.IsNormalized(name);
    }

    /// <summary>Gets a scalar's canonical combining class (UnicodeData.txt), 0 for most scalars.</summary>
    /// <param name="scalar">The scalar value.</param>
    /// <returns>The combining class.</returns>
    internal static int CombiningClass(int scalar)
    {
        var data = UnicodeNameData.CombiningClasses;
        var low = 0;
        var high = (data.Length / 3) - 1;
        while (low <= high)
        {
            var middle = (low + high) >> 1;
            var offset = middle * 3;
            if (scalar < data[offset])
            {
                high = middle - 1;
            }
            else if (scalar > data[offset + 1])
            {
                low = middle + 1;
            }
            else
            {
                return data[offset + 2];
            }
        }

        return 0;
    }

    /// <summary>Gets a scalar's simple case folding, or the scalar itself when it has none.</summary>
    /// <param name="scalar">The scalar value.</param>
    /// <returns>The folded scalar.</returns>
    internal static int Fold(int scalar)
    {
        var data = UnicodeNameData.SimpleCaseFolding;
        var low = 0;
        var high = (data.Length / 2) - 1;
        while (low <= high)
        {
            var middle = (low + high) >> 1;
            var key = data[middle * 2];
            if (scalar < key)
            {
                high = middle - 1;
            }
            else if (scalar > key)
            {
                low = middle + 1;
            }
            else
            {
                return data[(middle * 2) + 1];
            }
        }

        return scalar;
    }

    // The next folded scalar of a name, or a lone surrogate's own code unit.
    private static int Next(string name, ref int index)
    {
        if (Rune.DecodeFromUtf16(name.AsSpan(index), out var rune, out var count) != OperationStatus.Done)
        {
            return name[index++];
        }

        index += count;
        return Fold(rune.Value);
    }

    private sealed class Folding : IEqualityComparer<string>
    {
        public bool Equals(string? x, string? y)
        {
            if (x is null || y is null)
            {
                return ReferenceEquals(x, y);
            }

            int i = 0, j = 0;
            while (i < x.Length && j < y.Length)
            {
                if (Next(x, ref i) != Next(y, ref j))
                {
                    return false;
                }
            }

            return i == x.Length && j == y.Length;
        }

        public int GetHashCode(string name)
        {
            var hash = default(HashCode);
            for (var i = 0; i < name.Length;)
            {
                hash.Add(Next(name, ref i));
            }

            return hash.ToHashCode();
        }
    }

    private sealed class Scalar : IComparer<string>
    {
        public int Compare(string? x, string? y)
        {
            if (x is null || y is null)
            {
                return x is null ? (y is null ? 0 : -1) : 1;
            }

            var index = x.AsSpan().CommonPrefixLength(y);
            return index < x.Length && index < y.Length ? Rank(x[index]) - Rank(y[index]) : x.Length - y.Length;
        }

        // A code unit's rank in UTF-8 byte order: U+E000–U+FFFF below the surrogates, which encode U+10000 and above.
        private static int Rank(char unit)
            => unit < 0xD800 ? unit : unit < 0xE000 ? unit + 0x2000 : unit - 0x800;
    }
}
